import subprocess, hashlib, time, os
from datetime import datetime, timezone
for args in (['df','-h','/'], ['du','-sh','/home/hermes/.local/share/pilotq']):
    try:
        r = subprocess.run(args, capture_output=True, text=True, timeout=15)
