        print(args[0], 'timeout=15', flush=True)
args = ['journalctl',chr(45)*2+'user','-u','pilotq.service','-n','20',chr(45)*2+'no-pager','-o','short-iso']
try:
    r = subprocess.run(args, capture_output=True, text=True, timeout=15)
    print('journal returncode', r.returncode, 'stdout_lines', len(r.stdout.splitlines()), 'stdout_sha256', hashlib.sha256(r.stdout.encode()).hexdigest(), flush=True)
except subprocess.TimeoutExpired:
    print('journal timeout=15', flush=True)
def utc():
    return datetime.now(timezone.utc).isoformat()
start = time.monotonic()
print('P198-LONG-START', 'PID', os.getpid(), 'UTC', utc(), flush=True)
next_tick = 30
while True:
    elapsed = time.monotonic() - start
    if elapsed >= 310:
        break
    time.sleep(min(30, max(0, next_tick-elapsed), 310-elapsed))
    elapsed = time.monotonic() - start
    if elapsed >= next_tick:
        print('P198-TICK', elapsed, flush=True)
        next_tick += 30
